/**
 * Tests for the Release Relay controller, services and jobs.
 * Every test runs as an existing active System Administrator through System.runAs; inserting
 * a new user in these orgs fires community provisioning that exhausts test limits.
 */
@IsTest
private class RlyReleaseControllerTest {

    @TestSetup
    static void setup() {
        User admin = admin();
        for (PermissionSet ps : [SELECT Id FROM PermissionSet WHERE Name IN ('RLY_Admin', 'RLY_Approver')]) {
            if ([SELECT Id FROM PermissionSetAssignment WHERE AssigneeId = :admin.Id AND PermissionSetId = :ps.Id].isEmpty()) {
                insert new PermissionSetAssignment(AssigneeId = admin.Id, PermissionSetId = ps.Id);
            }
        }
        System.runAs(admin) {
            insert new List<RLY_Release__c>{
                new RLY_Release__c(Title__c = 'Running', Mode__c = 'Org changes', Org_Label__c = 'DEV',
                    Source_Branch__c = 'feature/running', Target_Branch__c = 'sit', Status__c = 'Workflow running'),
                new RLY_Release__c(Title__c = 'Open', Mode__c = 'Existing branch', Org_Label__c = 'DEV',
                    Source_Branch__c = 'feature/open-one', Target_Branch__c = 'sit', Status__c = 'PR open')
            };
        }
    }

    private static User admin() {
        return [SELECT Id FROM User WHERE Profile.Name = 'System Administrator' AND IsActive = true
                ORDER BY CreatedDate ASC LIMIT 1];
    }

