    /** A request whose pull request is open and whose checks were started a minute ago. */
    private static RLY_Release__c openRequest(String status) {
        RLY_Release__c req = new RLY_Release__c(Title__c = 'Review me', Mode__c = 'Org changes', Org_Label__c = 'DEV',
            Connection__c = 'Org_DEV1', Source_Branch__c = 'feature/review-me', Target_Branch__c = 'sit', Target_Environment__c = 'sit',
            Status__c = status, PR_Number__c = 42, Checks_Requested__c = Datetime.now().addMinutes(-1),
            Scan_Status__c = status == 'PR open' ? 'Pending' : 'Passed',
            Validation_Status__c = status == 'PR open' ? 'Pending' : 'Passed',
            Approval_Status__c = status == 'Ready for approval' ? 'Pending' : null);
        insert req;
        return [SELECT Id, Name, Status__c, Connection__c, Source_Branch__c, Target_Branch__c, Target_Environment__c, Run_ID__c,
                       Run_URL__c, PR_Number__c, PR_URL__c, Error_Message__c, Checks_Requested__c, Scan_Status__c, Scan_Violations__c,
                       Scan_Blocking__c, Scan_Result__c, Validation_Status__c, Validation_Result__c, Approval_Status__c,
                       Approved_On__c, Merge_Commit__c, Deploy_Status__c, Deploy_Result__c, CreatedById
                FROM RLY_Release__c WHERE Id = :req.Id];
    }

