                new List<String>{ 'org', '', 'feature/a', 'sit', items(true) },               // no title
                new List<String>{ 'org', 'Title', 'Feature/A', 'sit', items(true) },          // bad branch
                new List<String>{ 'org', 'Title', 'feature/a', 'sit', items(false) },         // not reviewed
                new List<String>{ 'org', 'Title', 'feature/a', 'sit', '[]' },                 // nothing selected
                new List<String>{ 'org', 'Title', 'feature/existing-work', 'sit', items(true) }, // branch exists
                new List<String>{ 'branch', 'Title', 'feature/missing', 'sit', null },        // branch missing
                new List<String>{ 'org', 'Title', 'feature/running', 'sit', items(true) }     // open request uses it
            };
            Test.startTest();
            for (List<String> b : bad) {
                try {
                    RlyReleaseController.raiseRequest(b[0], b[1], null, b[2], b[3], b[4], null);
                } catch (AuraHandledException e) {
                    refused++;
                }
            }
            Test.stopTest();
            System.assertEquals(bad.size(), refused, 'Every invalid request is refused');
        }
    }

